'use strict';
const $=s=>document.querySelector(s), NS='http://www.w3.org/2000/svg';
const state={places:[],codes:[],courses:[],tab:'places',query:'',selected:[],activeCode:null,view:{x:0,y:0,w:1806,h:785}};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clean=s=>String(s??'').trim().normalize('NFKC').toUpperCase();
const codeFor=c=>state.codes.find(x=>x.code===clean(c));
const placeFor=id=>state.places.find(p=>p.id===Number(id));
function locations(course){const c=codeFor(course.buildingCode);if(!c)return [];if(course.locationId){return c.locationIds.includes(Number(course.locationId))?[Number(course.locationId)]:[];}return c.locationIds;}
function isPrecise(course){return locations(course).length===1;}
function el(name,attrs){const n=document.createElementNS(NS,name);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));return n;}
function buildMap(){const layer=$('#hotspots');for(const p of state.places){const g=el('g',{'class':'hotspot',role:'button',tabindex:'0','aria-label':`${p.id} ${p.name}${p.codes.length?'，'+p.codes.join('、'):''}`,'aria-pressed':'false','data-id':p.id,'data-campus':p.campus});const title=el('title',{});title.textContent=`${p.name} ${p.codes.join(' / ')}`;g.append(title,el('polygon',{points:p.polygon,class:'area'}),el('circle',{cx:p.x,cy:p.y,r:11.6,class:'pin-disc'}));const t=el('text',{x:p.x,y:p.y,class:'pin-text'});t.textContent=p.id;g.append(t);g.addEventListener('click',e=>{e.stopPropagation();if(!dragMoved)selectPlace(p.id,false);});g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();e.stopPropagation();selectPlace(p.id,false)}});g.addEventListener('pointermove',e=>{if(pointers.size)return;const tip=$('#mapTooltip'),r=$('#mapStage').getBoundingClientRect();tip.textContent=p.name+(p.codes.length?' · '+p.codes.join(' / '):'');tip.hidden=false;tip.style.left=Math.max(8,Math.min(e.clientX-r.left+13,r.width-270))+'px';tip.style.top=Math.max(8,e.clientY-r.top-45)+'px';});g.addEventListener('pointerleave',()=>$('#mapTooltip').hidden=true);layer.append(g);}}
function highlight(){document.querySelectorAll('.hotspot').forEach(g=>{const yes=state.selected.includes(Number(g.dataset.id));g.classList.toggle('is-selected',yes);g.setAttribute('aria-pressed',String(yes));});}
function updateView(){const v=state.view;$('#campusMap').setAttribute('viewBox',`${v.x} ${v.y} ${v.w} ${v.h}`);$('#zoomLevel').textContent=Math.round(1806/v.w*100)+'%';$('#zoomIn').disabled=v.w<=301.01;$('#zoomOut').disabled=v.w>=1806;}
function clampView(){const v=state.view;v.x=Math.min(1806-v.w,Math.max(0,v.x));v.y=Math.min(785-v.h,Math.max(0,v.y));}
function resetView(){state.view={x:0,y:0,w:1806,h:785};updateView();}
function zoom(factor,anchor){const v=state.view,nw=Math.max(301,Math.min(1806,v.w/factor)),nh=nw*785/1806;const a=anchor||{x:v.x+v.w/2,y:v.y+v.h/2};const rx=(a.x-v.x)/v.w,ry=(a.y-v.y)/v.h;state.view={x:a.x-rx*nw,y:a.y-ry*nh,w:nw,h:nh};clampView();updateView();}
function focusPlaces(ids){const ps=ids.map(placeFor).filter(Boolean);if(!ps.length)return;let minX=Math.min(...ps.map(p=>p.x)),maxX=Math.max(...ps.map(p=>p.x)),minY=Math.min(...ps.map(p=>p.y)),maxY=Math.max(...ps.map(p=>p.y));const w=Math.min(1806,Math.max(690,maxX-minX+380,(maxY-minY+180)*1806/785));const h=w*785/1806;state.view={x:(minX+maxX)/2-w/2,y:(minY+maxY)/2-h/2,w,h};clampView();updateView();}
function selectPlace(id,focus=true){const p=placeFor(id);if(!p)return;state.selected=[p.id];state.activeCode=null;highlight();renderResults();renderDetails(p);if(focus)focusPlaces([p.id]);}
function selectCode(code){const c=codeFor(code);if(!c)return;state.activeCode=c.code;state.selected=c.locationIds.slice();highlight();renderResults();if(c.locationIds.length===1){renderDetails(placeFor(c.locationIds[0]),c);focusPlaces(c.locationIds);}else{const cs=state.courses.filter(x=>clean(x.buildingCode)===c.code);$('#details').innerHTML=`<div class="detail-top"><div><p class="eyebrow">館樓代碼 ${esc(c.code)}</p><h2>${esc(c.name)}</h2></div><button class="close-detail" aria-label="關閉地點資訊">×</button></div><p class="location-note">${esc(c.note)}</p>${c.locationIds.length?`<div class="group-choices">${c.locationIds.map(id=>`<button data-location="${id}">${esc(placeFor(id).name)}</button>`).join('')}</div>`:''}${courseContent(cs)}`;wireDetails();if(c.locationIds.length)focusPlaces(c.locationIds);}}
function courseContent(courses,locationId){
 if(!state.courses.length)return '<div class="course-message"><strong>課程資料待匯入</strong> · 尚未提供本學期課表，這不代表此處沒有開課。</div>';
 if(!courses.length)return '<div class="course-message">本次提供的課程表中，沒有可確認在此地點上課的資料。</div>';
 if(locationId){const precise=courses.filter(isPrecise),pending=courses.filter(c=>!isPrecise(c));return (precise.length?`<p class="course-section-title">已確認此館 · ${precise.length} 筆上課資訊</p>${precise.map(courseCard).join('')}`:'')+(pending.length?`<p class="course-section-title pending">館樓群組課程 · ${pending.length} 筆棟別待確認</p><p class="note">以下課程屬於同一館樓代碼，目前尚未確認是否在這一棟上課。</p>${pending.map(courseCard).join('')}`:'');}
 return `<p class="course-section-title">已收錄 ${courses.length} 筆上課資訊</p>${courses.map(courseCard).join('')}`;
}
function courseCard(c){const ids=locations(c),precise=isPrecise(c),building=codeFor(c.buildingCode);const teacher=[c.teacher||'教師未提供',c.department,c.courseId].filter(Boolean).map(esc).join(' · ');const day=c.day?'週'+(['','一','二','三','四','五','六','日'][Number(c.day)]||c.day):'星期未定';const when=[c.semester,day,c.periods?'第 '+c.periods+' 節':'節次未定'].filter(Boolean).map(esc).join(' · ');const room=c.rawRoom||(c.room?c.buildingCode+c.room:c.buildingCode+'（教室未定）');return `<article class="course-card"><strong>${esc(c.name)}</strong><p>${teacher}<br>${when}<br><span class="course-room">${building?esc(building.name)+' · ':''}${esc(room)}</span></p>${!precise?`<p class="course-location-pending">${!building?'原始地點尚未對應館樓':ids.length>1?'棟別／場地待確認':'實際位置待確認'}</p>`:''}${precise?`<button data-location="${ids[0]}">在地圖上查看</button>`:building?`<button data-code="${esc(clean(c.buildingCode))}">查看館樓範圍</button>`:''}</article>`;}
function courseMatches(c,q){return clean([c.name,c.courseId,c.teacher,c.department,c.buildingCode,c.rawRoom,c.room,codeFor(c.buildingCode)?.name].filter(Boolean).join(' ')).includes(q);}
function renderDetails(p,specificCode){const notes=p.codes.map(codeFor).filter(c=>c.note).map(c=>c.note);if(p.id===56)notes.push('「HRE 海工館」是否對應此館仍待確認，暫不自動連結課程。');const cs=state.courses.filter(c=>locations(c).includes(p.id)&&(!specificCode||clean(c.buildingCode)===specificCode.code));$('#details').innerHTML=`<div class="detail-top"><div><p class="eyebrow">${esc(p.campus)} / 地圖 ${String(p.id).padStart(2,'0')} / ${esc(p.grid)}</p><h2>${esc(p.name)}</h2><div class="detail-meta">${p.codes.map(c=>`<span class="code-badge">${esc(c)}</span>`).join('')||'<small>原代碼表未列館樓代碼</small>'}${specificCode?`<small>目前查看 ${esc(specificCode.name)}</small>`:''}</div></div><button class="close-detail" aria-label="關閉地點資訊">×</button></div>${notes.map(n=>`<p class="location-note">${esc(n)}</p>`).join('')}${courseContent(cs,p.id)}`;wireDetails();}
const initialDetails=$('#details').innerHTML;
function wireDetails(){$('#details').querySelector('.close-detail')?.addEventListener('click',()=>{state.selected=[];state.activeCode=null;highlight();renderResults();$('#details').innerHTML=initialDetails;});wireLocationButtons($('#details'));}
function wireLocationButtons(root){root.querySelectorAll('[data-location]').forEach(b=>b.addEventListener('click',()=>selectPlace(Number(b.dataset.location))));root.querySelectorAll('[data-code]').forEach(b=>b.addEventListener('click',()=>selectCode(b.dataset.code)));}
function matches(p,q){return clean([p.name,p.id,...p.codes,...p.codes.map(c=>codeFor(c)?.name)].join(' ')).includes(q);}
function renderResults(){const q=clean(state.query),root=$('#results');$('#resultHint').textContent=state.tab==='places'?'依地圖編號':'依課程資料';if(state.tab==='courses'){const list=state.courses.filter(c=>courseMatches(c,q));$('#resultSummary').textContent=`${list.length} 筆上課資訊`;root.innerHTML=list.length?list.map(courseCard).join(''):`<div class="empty"><div class="empty-icon" aria-hidden="true">▤</div><h3>${state.courses.length?'找不到符合的課程':'本學期課表，準備中'}</h3><p>${state.courses.length?'試試課名的一部分、教師姓名或館樓代碼。':'課程資料匯入後，就能搜尋課名，直接找到上課的大樓。'}</p><button id="emptyAction">${state.courses.length?'清除搜尋':'查看資料格式'}</button></div>`;$('#emptyAction')?.addEventListener('click',()=>state.courses.length?clearSearch():$('#guideDialog').showModal());wireLocationButtons(root);return;}
 const list=state.places.filter(p=>matches(p,q)),unmapped=state.codes.filter(c=>!c.locationIds.length&&q&&clean(c.code+' '+c.name).includes(q));$('#resultSummary').textContent=`${list.length} 個地點${unmapped.length?' · '+unmapped.length+' 組其他代碼':''}`;let html=list.map(p=>`<button class="place-item${state.selected.includes(p.id)?' selected':''}" data-location="${p.id}" ${state.selected.includes(p.id)?'aria-current="true"':''}><span class="place-number">${String(p.id).padStart(2,'0')}</span><span class="place-copy"><strong>${esc(p.name)}</strong><small>${esc(p.campus)} · ${esc(p.grid)}</small></span>${p.codes.length?`<span class="code-badge">${p.codes.length>1?p.codes[0]+' +':p.codes[0]}</span>`:''}</button>`).join('');html+=unmapped.map(c=>`<button class="place-item" data-code="${esc(c.code)}"><span class="place-number">—</span><span class="place-copy"><strong>${esc(c.name)}</strong><small>${c.code==='MZ-'?'不在校本部地圖範圍':'位置待確認'}</small></span><span class="code-badge">${esc(c.code)}</span></button>`).join('');root.innerHTML=html||'<div class="empty"><div class="empty-icon" aria-hidden="true">⌕</div><h3>找不到符合的館樓</h3><p>請試試名稱的一部分，或使用館樓代碼搜尋。</p><button id="clearSearch">清除搜尋</button></div>';$('#clearSearch')?.addEventListener('click',clearSearch);wireLocationButtons(root);}
function clearSearch(){state.query='';$('#search').value='';renderResults();$('#search').focus();}
function setTab(tab,focus=false){state.tab=tab;document.querySelectorAll('[data-tab]').forEach(b=>{const active=b.dataset.tab===tab;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});$('#results').setAttribute('aria-labelledby',tab==='places'?'placesTab':'coursesTab');renderResults();}
$('#search').addEventListener('input',e=>{state.query=e.target.value;renderResults();});$('#searchForm').addEventListener('submit',e=>{e.preventDefault();if(state.tab==='places'){const c=codeFor(state.query);if(c)return selectCode(c.code);const p=state.places.find(p=>matches(p,clean(state.query)));if(p)selectPlace(p.id);}else{$('#results [data-location],#results [data-code]')?.click();}});document.querySelectorAll('[data-tab]').forEach(b=>{b.addEventListener('click',()=>setTab(b.dataset.tab));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setTab(e.key==='Home'?'places':e.key==='End'?'courses':state.tab==='places'?'courses':'places',true);}});});
$('#guideOpen').addEventListener('click',()=>$('#guideDialog').showModal());$('#codesOpen').addEventListener('click',()=>$('#codesDialog').showModal());document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close-dialog').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});});
$('#zoomIn').addEventListener('click',()=>zoom(1.35));$('#zoomOut').addEventListener('click',()=>zoom(1/1.35));$('#resetMap').addEventListener('click',resetView);
const svg=$('#campusMap'),pointers=new Map();let dragMoved=false,gesture=null;
function toMap(clientX,clientY){const pt=svg.createSVGPoint();pt.x=clientX;pt.y=clientY;return pt.matrixTransform(svg.getScreenCTM().inverse());}
function startGesture(){if(pointers.size===1){const p=[...pointers.values()][0];gesture={type:'pan',start:p,view:{...state.view},scale:svg.getScreenCTM().a};}else if(pointers.size===2){const [a,b]=[...pointers.values()];gesture={type:'pinch',distance:Math.hypot(a.x-b.x,a.y-b.y)};}}
svg.addEventListener('pointerdown',e=>{if(e.button!==0)return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(pointers.size===1)dragMoved=false;startGesture();$('#mapTooltip').hidden=true;});
window.addEventListener('pointermove',e=>{if(!pointers.has(e.pointerId))return;pointers.set(e.pointerId,{x:e.clientX,y:e.clientY});if(gesture?.type==='pan'&&pointers.size===1){const dx=e.clientX-gesture.start.x,dy=e.clientY-gesture.start.y;if(Math.hypot(dx,dy)>5){dragMoved=true;svg.classList.add('dragging');svg.setPointerCapture(e.pointerId);state.view={...gesture.view,x:gesture.view.x-dx/gesture.scale,y:gesture.view.y-dy/gesture.scale};clampView();updateView();}}else if(gesture?.type==='pinch'&&pointers.size===2){const[a,b]=[...pointers.values()],dist=Math.hypot(a.x-b.x,a.y-b.y);if(gesture.distance>0){zoom(dist/gesture.distance,toMap((a.x+b.x)/2,(a.y+b.y)/2));dragMoved=true;}gesture.distance=dist;}});
function endPointer(e){if(!pointers.has(e.pointerId))return;pointers.delete(e.pointerId);if(svg.hasPointerCapture(e.pointerId))svg.releasePointerCapture(e.pointerId);svg.classList.remove('dragging');if(pointers.size)startGesture();else gesture=null;}
window.addEventListener('pointerup',endPointer);window.addEventListener('pointercancel',endPointer);
svg.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(-e.deltaY*.0015),toMap(e.clientX,e.clientY));},{passive:false});svg.addEventListener('keydown',e=>{if(e.key==='+'||e.key==='='){e.preventDefault();zoom(1.3);}if(e.key==='-'){e.preventDefault();zoom(1/1.3);}if(e.key==='Home'){e.preventDefault();resetView();}const shifts={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(shifts[e.key]){e.preventDefault();const [x,y]=shifts[e.key];state.view.x+=x*state.view.w*.12;state.view.y+=y*state.view.h*.12;clampView();updateView();}});
function registerTools(){const context=document.modelContext;if(!context?.registerTool)return;const tools=[{name:'search_campus',title:'搜尋海大館樓與課程',description:'搜尋目前地圖中的館樓、館樓代碼與已匯入的課程，不改變畫面。',inputSchema:{type:'object',properties:{query:{type:'string'}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(!input||typeof input.query!=='string')throw new Error('query must be a string');const q=clean(input.query);return {places:state.places.filter(p=>matches(p,q)).map(p=>({id:p.id,name:p.name,codes:p.codes})),codes:state.codes.filter(c=>clean(c.code+' '+c.name).includes(q)),courses:state.courses.filter(c=>courseMatches(c,q)),courseDataAvailable:state.courses.length>0};}},{name:'show_campus_location',title:'在地圖上查看海大地點',description:'選取地圖編號 1–70 的地點，顯示資訊並將地圖移到該處。',inputSchema:{type:'object',properties:{locationId:{type:'integer',minimum:1,maximum:70}},required:['locationId'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.locationId)||!placeFor(input.locationId))throw new Error('Unknown locationId');selectPlace(input.locationId);return {selectedId:state.selected[0],name:placeFor(input.locationId).name};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool)).catch(()=>{});}catch{}}}
async function init(){try{const responses=await Promise.all(['places','codes','courses'].map(async name=>{const r=await fetch(`data/${name}.json`);if(!r.ok)throw new Error('Unable to load '+name);return r.json();}));state.places=responses[0];state.codes=responses[1];const data=responses[2];state.courses=Array.isArray(data.courses)?data.courses:[];buildMap();renderResults();updateView();$('#courseCount').textContent=state.courses.length+' 筆';if(state.courses.length){$('.data-status').textContent=(data.edition||'課程資料')+' · '+state.courses.length+' 筆';$('#updateLabel').textContent=(data.coverage==='partial'?'部分課程資料 · ':'')+(data.updatedAt?'更新 '+data.updatedAt:'已匯入');$('#coverageNote').hidden=false;$('#coverageNote').textContent=data.coverage==='provided-complete'?'已更新課程表，共 '+state.courses.length+' 筆上課資訊。':'目前收錄 '+state.courses.length+' 筆上課資訊，尚非全校完整課表。';}$('#codeRows').innerHTML=state.codes.map(c=>`<tr><td>${esc(c.code)}</td><td>${esc(c.name)}${c.note?`<small>${esc(c.note)}</small>`:''}</td><td><button data-code="${esc(c.code)}">${c.locationIds.join('、')||(c.code==='MZ-'?'校外範圍':'待確認')}</button></td></tr>`).join('');$('#codeRows').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{$('#codesDialog').close();selectCode(b.dataset.code);}));registerTools();}catch(error){$('#resultSummary').textContent='資料載入失敗';$('#results').innerHTML='<div class="empty"><h3>暫時無法載入地圖資料</h3><p>請重新整理頁面再試一次。</p><button id="retryLoad">重新載入</button></div>';$('#retryLoad').addEventListener('click',()=>location.reload());console.error(error);}}
init();
